def lm(f,n,starts=25,seed=0):
    rng=np.random.default_rng(seed)
    best=(np.inf,None)
    for s in range(starts):
        p=rng.uniform(-1.5,1.5,n)
        lam=1e-2
        def res(p):
            r=f(p)-y
            return np.where(np.isfinite(r),r,1e3)
        r=res(p); c=r@r
        for it in range(200):
            J=np.empty((len(y),n))
            for k in range(n):
                dp=np.zeros(n); dp[k]=1e-6*max(1,abs(p[k]))
                J[:,k]=(res(p+dp)-r)/dp[k]
            H=J.T@J; g=J.T@r
            step=np.linalg.solve(H+lam*np.diag(np.diag(H)+1e-9),-g)
            pn=p+step; rn=res(pn); cn=rn@rn
            if cn<c: p,r,c=pn,rn,cn; lam=max(lam/3,1e-9)
            else: lam*=4
            if lam>1e8: break
        v=c/len(y)/np.var(y)
        if v<best[0]: best=(v,p.copy())
    return best
